// Ataque -> defensor -> multiplicador. Triângulo dos iniciais: Rachadinha > Centrão > Fuga > Rachadinha.
const CHART = {
  PROPINA:    { DELACAO: 2, CENTRAO: 2, LAVAGEM: 0.5 },
  LAVAGEM:    { PROPINA: 2, RACHADINHA: 2, DELACAO: 0.5 },
  DELACAO:    { LAVAGEM: 2, GOLPE: 2, FUGA: 2, PROPINA: 0.5, FAKE: 0.5 },
  GOLPE:      { CENTRAO: 2, RACHADINHA: 2, FAKE: 0.5 },
  FAKE:       { DELACAO: 2, GOLPE: 2, CENTRAO: 0.5 },
  CENTRAO:    { FAKE: 2, FUGA: 2, GOLPE: 0.5, RACHADINHA: 0.5 },
  RACHADINHA: { CENTRAO: 2, FAKE: 2, LAVAGEM: 0.5, FUGA: 0.5 },
  FUGA:       { GOLPE: 2, PROPINA: 2, RACHADINHA: 2, DELACAO: 0.5, CENTRAO: 0.5 },
};

function typeMult(atkType, defTypes) {
  let m = 1;
  for (const t of defTypes) m *= (CHART[atkType] && CHART[atkType][t]) || 1;
  return m;
}

